void rotateRight(TreeNode<T> node) {
     // Create a new parent node and make the original node a child of the new parent
     TreeNode<T> parent = new TreeNode<>();
     parent.left = node;

     // Find the sibling of the original node
     TreeNode<T> sibling = node.right;

