    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Class<?>[] resolvedArguments = new Class<?>[parameterizedType.getActualTypeArguments().length];
        for (int i = 0; i < resolvedArguments.length; i++) {
            Type argumentType = parameterizedType.getActualTypeArguments()[i];
            if (argumentType instanceof Class) {
                resolvedArguments[i] = (Class<?>) argumentType;
            } else if (argumentType instanceof ParameterizedType) {
                resolvedArguments[i] = resolveGenericType((ParameterizedType) argumentType, targetType)
            } else {
                resolvedArguments[i] = argumentType.getClass();
            }
        }
        return resolvedArguments;
    }

    private static Class<?> resolveGenericType(ParameterizedType genericType, Class<?> targetType) {
        return resolveTypeVariable(genericType.getRawType(), targetType);
    }

    private static Class<?> resolveTypeVariable(Type type, Class<?> targetType) {
        if (type instanceof Class) {
            return (Class<?>) type;
        } else if (type instanceof ParameterizedType) {
            return resolveGenericType((ParameterizedType) type, targetType);
        } else if (type instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) type;
            return resolveTypeVariable(resolveTypeVariable(typeVariable, targetType), targetType);
        } else {
            // Other types are not supported
            return null;
        }
    }
